function u(n,t=!1){return n?[[`found`,Object.values(n).reduce((r,i)=>r+(i||0),0),`found`],[`verified`,n.verified||0,`verified fixed`],[`pending`,n.pending||0,`awaiting your deployment`],[`unfixed`,(n.skipped||0)+(t?(n.open||0)+(n.review||0):0),`could not be fixed`]].filter(([,r])=>r>0).map(([r,i,o])=>({key:r,n:i,text:`${i} ${o}`})):[]}function d(n,t=!1){return u(n,t).map(e=>e.text).join(` · `)}function f(n){let t=Math.max(0,Math.round(n/1e3));if(t<60)return`${t} s`;let e=Math.floor(t/60);return e<60?`${e} min`:`${Math.floor(e/60)} h ${e%60} min`}var a=(n,t,e=`${t}s`)=>`${n} ${n===1?t:e}`;function g(n){let t=new Date(String(n||``));if(Number.isNaN(t.getTime()))return``;let e=t.getHours();return`${e%12||12}:${String(t.getMinutes()).padStart(2,`0`)} ${e<12?`AM`:`PM`}`}function p(n){try{return new URL(String(n||``)).host||String(n||``)}catch{return String(n||``)||`the site`}}var c=n=>n.charAt(0).toLowerCase()+n.slice(1);var l=n=>n.charAt(0).toUpperCase()+n.slice(1);export{g as a,u as c,f as i,c as n,l as o,d as r,p as s,a as t};